import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { peopleKey, useWatched, type Person } from '../people/usePeople';
import { usePersonRowAction } from '../people/usePersonRowAction';

/** Whether the signed-in user watches the person (yes/no), and a button that toggles it. A watcher is told
 *  (server side) when one of the person's claims is settled, approved or re-settled. */
function PersonWatch({ sheetId, personId }: { sheetId: string; personId: number }) {
  const watchedIds = useWatched(sheetId);
  const queryClient = useQueryClient();
  const watched = (watchedIds.data ?? []).includes(personId);

  const watch = useMutation({
    mutationFn: (body: { watch: boolean }) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/watch`, body),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
  });
  const announce = usePersonRowAction(sheetId, personId, watch.reset);

  return (
    <td>
      <span data-testid="person-watched">{watched ? 'yes' : 'no'}</span>{' '}
      <button
        type="button"
        data-testid="person-watch"
        disabled={watch.isPending || !watchedIds.isSuccess}
        onClick={() => {
          announce();
          watch.reset();
          watch.mutate({ watch: !watched });
        }}
      >
        {watched ? 'Unwatch' : 'Watch'}
      </button>
      {watch.isError && <span data-testid="person-error">{watch.error.message}</span>}
    </td>
  );
}

export const contributions = [
  PersonColumnHead.fill({ order: 55, Component: () => <th>Watched</th> }),
  PersonCells.fill({ order: 55, Component: PersonWatch }),
];
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Start or stop watching a person as the signed-in user (per user; it changes nothing on the sheet itself; a viewer is refused).
 *  Asking for the state already held writes nothing. */
public class WatchPerson {
    public void watch(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            @RequestBody WatchRequest request, ServerHttpConnection connection, PersonRepository repository,
            WatchRepository watches, Audit audit, Out<Person> person) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long pid;
        try {
            pid = Long.parseLong(personId == null ? "" : personId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such person");
        }
        Person found = repository.find(id, pid);
        if (found == null) {
            throw new BadRequestException("no such person");
        }
        if (request == null || request.watch() == null) {
            throw new BadRequestException("say whether to watch the person");
        }
        boolean on = request.watch();
        if (on != watches.watches(id, pid, by)) {
            if (on) {
                watches.watch(id, pid, by);
            } else {
                watches.unwatch(id, pid, by);
            }
            audit.record((on ? "PERSON_WATCHED" : "PERSON_UNWATCHED") + " sheet=" + id + " by=" + by + " name=" + found.name());
        }
        person.set(found);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, ObjectResponse<Person> response) {
        response.send(person);
    }
}
# Start or stop watching a person as the signed-in user (a viewer is refused).
guard:
  class: net.officefloor.hq.app.settings.RefuseViewer
  next: watch
watch:
  class: net.officefloor.hq.app.person.WatchPerson
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson

